/*
 * 74HC32 Quad OR Gate Test
 * Pin 1 (1A) and Pin 2 (1B) are inputs from buttons.
 * Pin 3 (1Y) is output to LED.
 *
 * OR Truth Table:  Y = A | B
 *   A=0, B=0  ->  Y=0  (LED OFF)
 *   A=0, B=1  ->  Y=1  (LED ON)
 *   A=1, B=0  ->  Y=1  (LED ON)
 *   A=1, B=1  ->  Y=1  (LED ON)
 *
 * 74HC32 Pinout:
 *   Pin 1: 1A (Input)   Pin 8:  3Y
 *   Pin 2: 1B (Input)   Pin 9:  3B
 *   Pin 3: 1Y (Output)  Pin 10: 3A
 *   Pin 4: 2A           Pin 11: 4Y
 *   Pin 5: 2B           Pin 12: 4B
 *   Pin 6: 2Y           Pin 13: 4A
 *   Pin 7: GND          Pin 14: VCC
 */

int pinA = 2;  // Button 1 -> Pin 1 (1A)
int pinB = 3;  // Button 2 -> Pin 2 (1B)
int ledPin = 13; // LED <- Pin 3 (1Y)

void setup() {
  pinMode(pinA, INPUT_PULLUP);
  pinMode(pinB, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  Serial.begin(115200);
  Serial.println("OR gate test ready");
  Serial.println("Pin 1=1A, Pin 2=1B, Pin 3=1Y");
}

void loop() {
  int a = digitalRead(pinA);
  int b = digitalRead(pinB);
  int logicA = (a == LOW) ? 1 : 0;
  int logicB = (b == LOW) ? 1 : 0;
  int orOut = logicA | logicB;
  digitalWrite(ledPin, orOut ? HIGH : LOW);
  Serial.print("1A=");
  Serial.print(logicA);
  Serial.print(" 1B=");
  Serial.print(logicB);
  Serial.print(" -> 1Y=");
  Serial.println(orOut ? "1 (ON)" : "0 (OFF)");
  delay(100);
}
